"""Clock-domain validation and per-stream rate / latency / drop / order diagnostics. PURE.

Two clocks are involved for every message:
  stamp : header.stamp written by the producer (camera driver, cuVSLAM, skybeta)
  rx    : the time OUR node received it (node clock)
Capture-to-receipt latency (rx - stamp) is meaningful ONLY when both are on the same time base.
`ClockDomainMonitor` decides that from the data instead of assuming it: a stable offset within
[min_offset_s, max_offset_s] means comparable; a stamp ahead of receipt, a zero-based (uptime or sim
time) stamp against a wall-clock receiver, or an offset that steps, means MISMATCH and no latency is
reported. Evidence (2026-11-07 drone bag): /visual_slam/tracking/odometry header stamps and receipt
times were both Unix epoch, offset 0.05-0.41 s (p50 0.08 s).

Rates are measured from the messages actually received (both clocks), never from a companion topic:
CameraInfo can run at 30 Hz while depth images arrive slower or not at all (the same bag recorded
/oak/stereo/camera_info at 30 Hz and no depth image at all).
"""
from __future__ import annotations

import math
from collections import deque
from dataclasses import dataclass
from typing import Deque, Dict, Optional

import numpy as np

COMPARABLE, MISMATCH, UNDETERMINED = "COMPARABLE", "MISMATCH", "UNDETERMINED"


def _finite(*xs) -> bool:
    return all(isinstance(x, (int, float)) and math.isfinite(x) for x in xs)


@dataclass
class ClockParams:
    min_offset_s: float = -0.02      # rx may lead stamp by at most this (clock jitter between hosts)
    max_offset_s: float = 2.0        # a capture->receipt delay above this is a different clock, not latency
    step_s: float = 0.5              # a sudden offset change larger than this = clock step
    min_samples: int = 5
    window: int = 50


class ClockDomainMonitor:
    def __init__(self, prm: ClockParams = ClockParams()):
        self.prm = prm
        self.offsets: Deque[float] = deque(maxlen=prm.window)
        self.state = UNDETERMINED
        self.reason = "too few samples"
        self.steps = 0

    def update(self, stamp: float, rx: float) -> None:
        if not _finite(stamp, rx) or stamp <= 0.0:
            return                                      # unstamped messages say nothing about the domain
        off = rx - stamp
        if len(self.offsets) >= self.prm.min_samples:
            med = float(np.median(self.offsets))
            if abs(off - med) > self.prm.step_s:
                self.steps += 1
                self.offsets.clear()                    # re-learn the new offset from scratch
        self.offsets.append(off)
        self._judge()

    def _judge(self) -> None:
        p = self.prm
        if len(self.offsets) < p.min_samples:
            self.state, self.reason = (MISMATCH, "clock step") if self.steps else (UNDETERMINED, "too few samples")
            return
        med = float(np.median(self.offsets))
        if med < p.min_offset_s:
            self.state, self.reason = MISMATCH, "stamps ahead of receipt by %.3f s" % -med
        elif med > p.max_offset_s:
            self.state, self.reason = MISMATCH, "stamps %.1f s behind receipt (different time base)" % med
        else:
            self.state, self.reason = COMPARABLE, ""

    @property
    def comparable(self) -> bool:
        return self.state == COMPARABLE

    def latency(self, stamp: float, rx: float) -> Optional[float]:
        """rx - stamp, or None when the clocks are not known to be comparable."""
        if not self.comparable or not _finite(stamp, rx):
            return None
        return rx - stamp


def _pct(a, q):
    return float(np.percentile(a, q)) if len(a) else None


@dataclass
class StreamParams:
    window: int = 300                # messages kept for rate/latency statistics
    gap_factor: float = 2.0          # stamp interval > gap_factor * median interval = gap (dropped frames)
    min_period_samples: int = 5


class StreamMonitor:
    """Diagnostics for one topic. on_message() returns whether the message should be used as the
    newest observation (False for unstamped, duplicate or out-of-order stamps)."""

    def __init__(self, name: str, prm: StreamParams = StreamParams(), clock: Optional[ClockParams] = None):
        self.name = name
        self.prm = prm
        self.clock = ClockDomainMonitor(clock or ClockParams())
        self.rx: Deque[float] = deque(maxlen=prm.window)
        self.stamps: Deque[float] = deque(maxlen=prm.window)
        self.lat: Deque[float] = deque(maxlen=prm.window)
        self.proc: Deque[float] = deque(maxlen=prm.window)
        self.count = 0
        self.unstamped = 0
        self.out_of_order = 0
        self.duplicates = 0
        self.gaps = 0
        self.dropped_est = 0
        self.max_gap_s = 0.0
        self.last_stamp: Optional[float] = None
        self.last_rx: Optional[float] = None

    def on_message(self, stamp: Optional[float], rx: float) -> bool:
        self.count += 1
        self.rx.append(rx)
        if stamp is None or not _finite(stamp) or stamp <= 0.0:
            self.unstamped += 1
            return False
        self.clock.update(stamp, rx)
        if self.last_stamp is not None:
            if abs(stamp - self.last_stamp) < 1e-9:
                self.duplicates += 1
                return False
            if stamp < self.last_stamp:
                self.out_of_order += 1
                return False
            dt = stamp - self.last_stamp
            per = self.median_period()
            if per is not None and dt > self.prm.gap_factor * per:
                self.gaps += 1
                self.dropped_est += max(0, int(round(dt / per)) - 1)
            self.max_gap_s = max(self.max_gap_s, dt)
        self.stamps.append(stamp)
        self.last_stamp, self.last_rx = stamp, rx
        lat = self.clock.latency(stamp, rx)
        if lat is not None:
            self.lat.append(lat)
        return True

    def record_processing(self, seconds: float) -> None:
        if _finite(seconds) and seconds >= 0:
            self.proc.append(seconds)

    def median_period(self) -> Optional[float]:
        if len(self.stamps) < self.prm.min_period_samples:
            return None
        d = np.diff(np.asarray(self.stamps))
        d = d[d > 0]
        return float(np.median(d)) if len(d) else None

    @staticmethod
    def _rate(ts) -> Optional[float]:
        if len(ts) < 2:
            return None
        span = ts[-1] - ts[0]
        return (len(ts) - 1) / span if span > 0 else None

    def ages(self, now: float) -> Dict[str, Optional[float]]:
        return {"rx_age_s": None if self.last_rx is None else now - self.last_rx,
                "stamp_age_s": None if (self.last_stamp is None or not self.clock.comparable) else now - self.last_stamp}

    def summary(self, now: Optional[float] = None, include_processing: bool = True) -> Dict:
        lat = list(self.lat)
        out = {"count": self.count, "rate_rx_hz": self._rate(list(self.rx)), "rate_stamp_hz": self._rate(list(self.stamps)),
               "clock": self.clock.state, "clock_reason": self.clock.reason, "clock_steps": self.clock.steps,
               "latency_p50_s": _pct(lat, 50), "latency_p95_s": _pct(lat, 95), "latency_max_s": max(lat) if lat else None,
               "unstamped": self.unstamped, "out_of_order": self.out_of_order, "duplicates": self.duplicates,
               "gaps": self.gaps, "dropped_est": self.dropped_est, "max_gap_s": self.max_gap_s}
        if include_processing:
            pr = list(self.proc)
            out.update(proc_p50_s=_pct(pr, 50), proc_max_s=max(pr) if pr else None)
        if now is not None:
            out.update(self.ages(now))
        return out
